from pptx import Presentation
prs=Presentation('/app/output/final_deck.pptx')
print('slides', len(prs.slides), 'size', prs.slide_width, prs.slide_height)
for i,s in enumerate(prs.slides,1):
    texts=[]
    for sh in s.shapes:
        if hasattr(sh,'text') and sh.text.strip(): texts.append(sh.text.strip().replace('\n',' | '))
    print(i, ' :: '.join(texts[:6]))
